import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "A", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "B", unitPriceCents: 2000, weightGrams: 300 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // Updated price: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });
  });

  describe("inventory check", () => {
    it("passes with available: true", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when available: false", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("checks multiple products and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(800 * 0.1) = 80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh, inventory check, discount, async tax, and shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "FR",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1000) // productA stays same
          .mockResolvedValueOnce(3000), // productB updated to 3000
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1000*2 + 3000*1 = 5000
      expect(result.totals.subtotalCents).toBe(5000);
      // discount = floor(5000 * 10%) = 500
      expect(result.totals.discountCents).toBe(500);
      // discountedSubtotal = 5000 - 500 = 4500
      // tax = floor(4500 * 0.2) = 900
      expect(result.totals.taxCents).toBe(900);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 4500 + 900 + 500 = 5900
      expect(result.totals.totalCents).toBe(5900);
    });

    it("works without any collaborators (uses defaults)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity], [-Infinity]])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("floors fractional cents (10% of 999 = 99, not 99.9)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotals", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 100000 = 15000
      expect(policy.computeDiscountCents(100000)).toBe(15000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("clamps to subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns subtotal when equal to amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 100% policies sum to 200% — composite returns sum, cart clamps
      const policies = [
        new PercentageDiscountPolicy(100),
        new PercentageDiscountPolicy(100),
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });

    it("clamps negative individual results to 0 before summing", () => {
      const noDiscount = new NoDiscountPolicy(); // returns 0
      const fixed = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([noDiscount, fixed], "sum");
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies policies sequentially to remaining subtotal", () => {
      // 10% of 1000 = 100, remaining = 900; then fixed 200 off 900 = 200
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters: fixed first then percentage", () => {
      // Fixed 200 off 1000 → remaining 800; 10% of 800 = 80
      const policies = [
        new FixedAmountDiscountPolicy(200),
        new PercentageDiscountPolicy(10),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(280);
    });

    it("stops reducing once remaining hits zero", () => {
      const policies = [
        new FixedAmountDiscountPolicy(600),
        new FixedAmountDiscountPolicy(600),
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      // First takes 600 from 1000 → remaining 400, second takes min(600, 400) = 400
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // sum mode: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

