import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "A", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "B", unitPriceCents: 2000, weightGrams: 300 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // Updated price: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });
  });

  describe("inventory check", () => {
    it("passes with available: true", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when available: false", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("checks multiple products and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal 1000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(800 * 0.1) = 80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh, inventory check, discount, async tax, and shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "FR",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1000) // productA stays same
          .mockResolvedValueOnce(3000), // productB updated to 3000
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1000*2 + 3000*1 = 5000
      expect(result.totals.subtotalCents).toBe(5000);
      // discount = floor(5000 * 10%) = 500
      expect(result.totals.discountCents).toBe(500);
      // discountedSubtotal = 5000 - 500 = 4500
      // tax = floor(4500 * 0.2) = 900
      expect(result.totals.taxCents).toBe(900);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 4500 + 900 + 500 = 5900
      expect(result.totals.totalCents).toBe(5900);
    });

    it("works without any collaborators (uses defaults)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });
  });
});

